@page "/enroll"
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p class="text-muted">Complete this form to submit an enrollment request. All fields except comments are required.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Your enrollment request for <strong>@enrolledCourseName</strong> has been submitted successfully.</p>
        <hr>
        <a href="/courses" class="btn btn-outline-success">Browse More Courses</a>
        <a href="/" class="btn btn-outline-secondary ms-2">Return Home</a>
    </div>
}
else
{
    @if (validationError is not null)
    {
        <div class="alert alert-danger">@validationError</div>
    }

    <form method="post" @formname="enrollment" class="row g-3" style="max-width: 600px;">
        <AntiforgeryToken />

        <div class="col-12">
            <label for="studentName" class="form-label">Full Name</label>
            <input type="text" class="form-control" id="studentName" name="Model.StudentName"
                   value="@Model.StudentName" required />
        </div>

        <div class="col-12">
            <label for="studentId" class="form-label">Student ID</label>
            <input type="text" class="form-control" id="studentId" name="Model.StudentId"
                   value="@Model.StudentId" required placeholder="e.g., S12345678" />
        </div>

        <div class="col-12">
            <label for="courseId" class="form-label">Course</label>
            <select class="form-select" id="courseId" name="Model.CourseId" required>
                <option value="">— Select a course —</option>
                @foreach (var course in Catalog.GetAllCourses().OrderBy(c => c.Id))
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">
                        @course.Id — @course.Title (@course.Credits cr.)
                    </option>
                }
            </select>
        </div>

        <div class="col-12">
            <label for="comments" class="form-label">Comments <span class="text-muted">(optional)</span></label>
            <textarea class="form-control" id="comments" name="Model.Comments" rows="3">@Model.Comments</textarea>
        </div>

        <div class="col-12">
            <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
            <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
        </div>
    </form>
}

@code {
    [SupplyParameterFromForm] public EnrollmentRequest Model { get; set; } = new();
    [SupplyParameterFromQuery] public string? CourseId { get; set; }

    private bool submitted;
    private string? validationError;
    private string? enrolledCourseName;

    protected override void OnInitialized()
    {
        if (!string.IsNullOrEmpty(CourseId) && string.IsNullOrEmpty(Model.CourseId))
        {
            Model.CourseId = CourseId;
        }
    }

    protected override void OnParametersSet()
    {
        if (HttpMethods.IsPost(HttpContext.Request.Method))
        {
            HandleSubmit();
        }
    }

    [CascadingParameter] public HttpContext HttpContext { get; set; } = default!;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(Model.StudentName))
        {
            validationError = "Please enter your full name.";
            return;
        }

        if (string.IsNullOrWhiteSpace(Model.StudentId))
        {
            validationError = "Please enter your student ID.";
            return;
        }

        if (string.IsNullOrWhiteSpace(Model.CourseId))
        {
            validationError = "Please select a course.";
            return;
        }

        var course = Catalog.GetCourse(Model.CourseId);
        if (course is null)
        {
            validationError = "The selected course was not found.";
            return;
        }

        if (Catalog.SubmitEnrollment(Model))
        {
            enrolledCourseName = $"{course.Id} — {course.Title}";
            submitted = true;
        }
        else
        {
            validationError = "An error occurred. Please try again.";
        }
    }
}

