    {
        if (string.IsNullOrWhiteSpace(Model.StudentName))
        {
            validationError = "Please enter your full name.";
            return;
        }

        if (string.IsNullOrWhiteSpace(Model.StudentId))
        {
            validationError = "Please enter your student ID.";
            return;
        }

        if (string.IsNullOrWhiteSpace(Model.CourseId))
        {
            validationError = "Please select a course.";
            return;
        }

        var course = Catalog.GetCourse(Model.CourseId);
        if (course is null)
        {
            validationError = "The selected course was not found.";
            return;
        }

        if (Catalog.SubmitEnrollment(Model))
        {
            enrolledCourseName = $"{course.Id} — {course.Title}";
            submitted = true;
        }
        else
        {
            validationError = "An error occurred. Please try again.";
        }
    }
}

